import { z } from 'zod';
import { ProfileReferenceInputSchema } from './design-profile';
import {
  ReferenceIdSchema,
  ReferenceProviderSchema,
} from './reference-connectors';

export const ReferenceContentsPageSchema = z.object({
  accountId: ReferenceIdSchema,
  collectionId: ReferenceIdSchema,
  references: z.array(
    ProfileReferenceInputSchema.extend({ provider: ReferenceProviderSchema }),
  ),
  total: z.number().int().nonnegative().nullable(),
  nextCursor: z.string().min(1).max(20_000).nullable(),
  isCollectionComplete: z.boolean(),
});
export type ReferenceContentsPage = z.infer<typeof ReferenceContentsPageSchema>;
export class ReferenceConnectionError extends Error {
  constructor(readonly reason: 'not_connected' | 'account_changed') {
    super(
      reason === 'not_connected'
        ? 'Connect this reference provider, then repeat discovery.'
        : 'The connected reference account changed. Discover the account again and review another plan.',
    );
    this.name = 'ReferenceConnectionError';
  }
}
